CREATE TABLE IF NOT EXISTS project_capital_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, amount numeric(20,2) NOT NULL, currency text NOT NULL DEFAULT 'NGN', purpose text NOT NULL, financing_stage text NOT NULL DEFAULT 'pre_development', target_date date, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());